```cpp
#include <iostream>
#include <string>

#include "pugixml.hpp"

// Helper function to convert characters within square brackets into attributes in tags.
std::string escape_attribute(const char *str) {
    std::string result;
    int in_escape = 0;

    for (const auto c : std::string(str)) {
        switch (c) {
            case '[':
                if (!in_escape) {
                    result += "[";
                }
                in_escape = 1;
                break;
            case ']':
                if (in_escape) {
                    result += "]";
                } else {
                    result += c;
                }
                in_escape = 0;
                break;
            default:
                if (in_escape) {
                    result += c;
                } else {
                    result += static_cast<char>(std::toupper(c));
                }
                break;
        }
    }

    return result;
}

// Function to convert Markdown to HTML (using pugixml)
std::string markdown_to_html(const std::string& input_markdown) {
    pugi::xml_document doc;
    pugi::xml_node root;

    try {
        // Parse the input string as XML, allowing unescaped ampersands (&).
        doc.parse(input_markdown.c_str(), nullptr,&pugi::parse_declaration, pugi::parse_default,
                   "UTF-8", &pugi::parse_all);

        // Check if parsing was successful.
        if (doc.empty()) {
            throw std::invalid_argument("Invalid Markdown format.");
        }

        // Traverse the parsed document, recursively converting Markdown elements to HTML.
        root = doc.first_child();

        std::stringstream ss;
        bool in_paragraph = false;  // Track whether we're currently inside a paragraph.

        ss << "<div><![CDATA[";

        for (pugi::xml_node it = root.child("p"); it; it = it.next_sibling("p")) {

            // Converting paragraphs to `<p>` tags.
            if (!in_paragraph) {
                ss << "<p>";
                in_paragraph = true;
            }

            // Handling inline formatting, like emphasis and links.
            it.append_child(pugi::node_pcdata).append_value(it.text().value());

            for (pugi::xml_node child = it.first_child(); child; child = child.next_sibling()) {
                std::string tag;

                // Heading element.
                if (child.name() == "h1" || child.name() == "h2" || child.name() == "h3") {
                    int level = child.node_type() - pugi::node_element + 1;
                    tag = "<h" + std::to_string(level) + ">";
                } else if (child.name() == "br") {  // Break element.
                    tag = "<br/>";
                } else if (child.name() == "a") {  // Link element.
                    const char *title = child.attribute("title").value();
                    tag = "<a href=\"";
                    auto href = child.attribute("href");
                    tag += href? href.value() : "";
                    tag += quotes(href? " " : "") + "\">";

                    // Add title attribute only if present.
                    if (title!= nullptr) {
                        tag += " title=\"";
                        tag += quote(title);
                        tag += "\"";
                    }
                    tag += child.last_child().value();
                    tag += "</a>";
                } else if (child.name() == "strong" || child.name() == "em") {  // Inline markup.
                    tag = "<" + (child.node_type() == pugi::node_element? escape_attribute(child.name().value())
                                                              : "span")
                         + (" class=\"" + (child.node_type() == pugi::node_element? child.name().value()
                                                                                  : "mark")
                             + "\""
                           );
                    child.type() == pugi::node_pcdata && tag.pop_back();  // Do not add closing '>' for text nodes.
                }

                if (!tag.empty()) {
                    ss << tag;
                }
            }

            if (itSibling := it.next_sibling("p")) {
                ss << "</p><![CDATA[";
                in_paragraph = false;
            } else if (!in_paragraph) {
                ss << "</p>";
                in_paragraph = false;
            }
        }

        ss << "]]></div>";

        return ss.str();
    } catch (const std::exception& e) {
        throw std::invalid_argument(e.what());
    }
}

// Utility to safely include quotes in output HTML attribute values.
inline std::string quotes(const std::string& val) {
    std::string result;
    bool first = true;

    for (char c : val) {
        if (first) {
            first = false;
        } else {
            result += "&amp;";
        }

        switch (c) {
            case '"': result += "&quot;"; break;
            case '<': result += "&lt;"; break;
            case '&': result += "&amp;"; break;
            default: result += c; break;
        }
    }

    return result;
}

