}

% Helper macro: Generates a table row containing pieces
\newcommand{\rowBuilder}[2]{%
  \def\xs{}%
  \foreach \col [count=\i] in {#1}{%
    \def\tmp##1##2##3{%
      \pgfmathtruncatemacro\num{##3}
      \edef\xs{\xs
        \expandafter\cellStyle\expandafter[\num]{\col}{\num}%
      }%
    }%
    \tmp\col\space0\space%
  }%
  \(xs)%
}

% Define function to parse FEN strings into pieces and board layout
\newcommand{\parseFEN}[1]{
  \renewcommand*{\WhiteSquareColor}{black!10} % Default white square color is light grey
  \renewcommand*{\BlackSquareColor}{white!80} % Default black square color is dark grey

  \def\fenComponents{}
  \def\boardState{}

  % Extracting components from provided FEN string
  \foreach \c [count=\i] in {#1}{
    \expandafter\ifdefempty\expandafter{\c}\relax
    {}% do nothing
    \else
      \edef\tempComponent{\c}
      \ifnum\i>5
